return $input.all().map(item => {
  const row = item.json;

  const fraudScore = Number(row["Score Antifraude"]);

  const risk_anti_fraud = fraudScore >= 60
    ? "low"
    : fraudScore >= 30
      ? "mid"
      : "high";

  const transactionId = String(row.ID);

  return {
    json: {
      source_type: "transaction",
      source_id: transactionId,
      transaction_id: transactionId,

      text_for_embedding: [
        `Transacción: ${transactionId}`,
        `Cliente: ${row.Cliente}`,
        `Comercio: ${row.Comercio}`,
        `Monto: ${row["Monto (USD)"]} USD`,
        `Fecha: ${row.Fecha}`,
        `Método de pago: ${row["Método de Pago"]}`,
        `País: ${row.País}`,
        `Canal: ${row.Canal}`,
        `Dispositivo: ${row.Dispositivo}`,
        `Score antifraude: ${fraudScore}`,
        `Riesgo: ${risk_anti_fraud}`,
        `Estado: ${row.Estado}`,
        `Notas: ${row.Notas ?? ""}`
      ].join("\n"),

      data: {
        transaction_id: transactionId,
        client: row.Cliente,
        merchant: row.Comercio,
        amount: Number(row["Monto (USD)"]),
        date: row.Fecha,
        payment_method: row["Método de Pago"],
        country: row.País,
        channel: row.Canal,
        device: row.Dispositivo,
        fraud_score: fraudScore,
        risk_anti_fraud,
        status: row.Estado,
        notes: row.Notas ?? null
      }
    }
  };
});

