parameters.jsCode:
return $input.all().map(item => {
  const row = item.json;

  const transactionId = String(row["ID Transacción"] ?? "");
  const timestamp = String(row["Timestamp"] ?? "");
  const event = String(row["Evento"] ?? "");
  const code = String(row["Código"] ?? "");

  // Identificador estable para el evento
  const sourceId = [
    transactionId,
    timestamp,
    event,
    code
  ].join("_");

  return {
    json: {
      source_type: "event_log",
      source_id: sourceId,
      transaction_id: transactionId,
      text_for_embedding: [
        `Transacción: ${transactionId}`,
        `Fecha y hora: ${timestamp}`,
        `Evento: ${event}`,
        `Servicio o módulo: ${row["Servicio / Módulo"]}`,
        `Código: ${code}`,
        `Detalle: ${row["Detalle"]}`,
        `Severidad: ${row["Severity"]}`
      ].join("\n"),
      data: {
        timestamp: timestamp,
        transaction_id: transactionId,
        event: event,
        service: row["Servicio / Módulo"],
        code: code,
        detail: row["Detalle"],
        severity: row["Severity"]
      }
    }
  };
});
